contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        uint cBalanceBefore = address(c).balance;
        uint callerBalanceBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint cBalanceAfterDeposit = address(c).balance;
        uint callerBalanceAfterDeposit = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool withdrawReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint cBalanceAfterWithdraw = address(c).balance;

        assert(
            cBalanceAfterDeposit >= cBalanceBefore + depositAmount &&
            callerBalanceAfterDeposit >= callerBalanceBefore &&
            (
                withdrawReverted ||
                cBalanceAfterWithdraw + callerBalanceAfterDeposit == cBalanceAfterDeposit
            )
        );
    }

    receive() external payable {}
}

