// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount, uint256 withdrawAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint cBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { callerBalanceBefore = __r; } catch { return; }
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint cBalanceAfterDeposit = address(c).balance;
        uint256 callerBalanceAfterDeposit;
        try c.getBalance(address(this)) returns (uint256 __r) { callerBalanceAfterDeposit = __r; } catch { return; }
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint cBalanceAfterWithdraw = address(c).balance;
        assertTrue(cBalanceAfterDeposit >= cBalanceBefore + depositAmount &&
            callerBalanceAfterDeposit >= callerBalanceBefore &&
            (
                withdrawReverted ||
                cBalanceAfterWithdraw + callerBalanceAfterDeposit == cBalanceAfterDeposit
            ));
    }

    function testFuzz_run(uint256 depositAmount, uint256 withdrawAmount) public {
        _run(depositAmount, withdrawAmount);
    }

    receive() external payable {}
}
